package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.HashMap;
import java.util.Map.Entry;
import java.util.Map;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.BytesUtils;
import org.apache.commons.compress.utils.CharsetNames;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveInputStream_read_TriageGen2Test {

    /**
     * Helper to create a minimal valid TAR entry byte array.
     * A TAR entry consists of a 512-byte header followed by the file data.
     */
    private byte[] createTarData(String fileName, byte[] content) {
        byte[] header = new byte[512];
        byte[] nameBytes = fileName.getBytes(StandardCharsets.UTF_8);
        System.arraycopy(nameBytes, 0, header, 0, Math.min(nameBytes.length, 100));

        // Set size in header (octal) at offset 124
        String sizeStr = String.format("%011o", content.length);
        for (int i = 0; i < sizeStr.length(); i++) {
            header[124 + i] = (byte) sizeStr.charAt(i);
        }

        byte[] fullData = new byte[512 + content.length];
        System.arraycopy(header, 0, fullData, 0, 512);
        System.arraycopy(content, 0, fullData, 512, content.length);

        // TAR files must be padded to 512-byte blocks
        int paddingNeeded = (512 - (fullData.length % 512)) % 512;
        byte[] paddedData = new byte[fullData.length + paddingNeeded];
        System.arraycopy(fullData, 0, paddedData, 0, fullData.length);

        return paddedData;
    }

    @Test
    public void testRead_ThrowsIllegalStateException_WhenNoCurrentEntry() throws IOException {
        byte[] data = createTarData("test.txt", new byte[0]);
        try (TarArchiveInputStream tais = new TarArchiveInputStream(new ByteArrayInputStream(data))) {
            byte[] buf = new byte[10];
            // We haven't called getNextTarEntry(), so currEntry is null
            try {
                tais.read(buf, 0, 10);
                Assert.fail("Should have thrown IllegalStateException");
            } catch (IllegalStateException e) {
                Assert.assertEquals("No current entry tar", "No current tar entry", e.getMessage());
            }
        }
    }

    @Test
    public void testRead_ReturnsMinusOne_WhenHasHitEOF() throws IOException {
        byte[] data = createTarData("test.txt", new byte[10]);
        try (TarArchiveInputStream tais = new TarArchiveInputStream(new ByteArrayInputStream(data))) {
            tais.getNextTarEntry();
            byte[] buf = new byte[10];

            // Read all data
            tais.read(buf, 0, 10);

            // Simulate EOF state by trying to read again after content is exhausted
            // In the provided code, if totalRead == -1, hasHitEOF becomes true
            // We trigger this by providing an empty stream or reaching end of content

            // Attempting to read more than available or after EOF
            int result = tais.read(buf, 0, 10);
            // If the underlying stream returns -1
            if (result == -1) {
                // Second call should return -1 immediately due to hasHitEOF
                Assert.assertEquals(-1, tais.read(buf, 0, 10));
            }
        }
    }

    @Test
    public void testRead_ReturnsMinusOne_WhenEntryOffsetGreaterThanEntrySize() throws IOException {
        byte[] content = "hello".getBytes();
        byte[] data = createTarData("test.txt", content);
        try (TarArchiveInputStream tais = new TarArchiveInputStream(new ByteArrayInputStream(data))) {
            tais.getNextTarEntry();

            byte[] buf = new byte[10];
            // Read exactly the content
            tais.read(buf, 0, 5);

            // After reading all bytes, entryOffset should be >= entrySize
            // The next read should return -1
            Assert.assertEquals(-1, tais.read(buf, 0, 5));
        }
    }

    @Test
    public void testRead_Success_NormalFlow() throws IOException {
        byte[] content = "Hello World".getBytes();
        byte[] data = createTarData("test.txt", content);
        try (TarArchiveInputStream tais = new TarArchiveInputStream(new ByteArrayInputStream(data))) {
            tais.getNextTarEntry();

            byte[] buf = new byte[5];
            int offset = 0;

            // Read 1: "Hello"
            int read1 = tais.read(buf, offset, 5);
            Assert.assertEquals(5, read1);
            Assert.assertEquals("Hello", new String(buf, 0, 5));

            // Read 2: " Worl"
            int read2 = tais.read(buf, offset, 5);
            Assert.assertEquals(5, read2);
            Assert.assertEquals(" Worl", new String(buf, 0, 5));

            // Read 3: "d" (numToRead is capped by available())
            int read3 = tais.read(buf, offset, 5);
            Assert.assertEquals(1, read3);
            Assert.assertEquals("d", new String(buf, 0, 1));
        }
    }

    @Test
    public void testRead_CappedByAvailable() throws IOException {
        byte[] content = "ABC".getBytes();
        byte[] data = createTarData("test.txt", content);
        try (TarArchiveInputStream tais = new TarArchiveInputStream(new ByteArrayInputStream(data))) {
            tais.getNextTarEntry();

            byte[] buf = new byte[10];
            // available() should be 3. numToRead is 10.
            int read = tais.read(buf, 0, 10);

            Assert.assertEquals(3, read);
            Assert.assertEquals("ABC", new String(buf, 0, 3));
        }
    }

    @Test
    public void testRead_OffsetParameter() throws IOException {
        byte[] content = "ABCDE".getBytes();
        byte[] data = createTarData("test.txt", content);
        try (TarArchiveInputStream tais = new TarArchiveInputStream(new ByteArrayInputStream(data))) {
            tais.getNextTarEntry();

            byte[] buf = new byte[10];
            int offset = 2;
            int read = tais.read(buf, offset, 3);

            Assert.assertEquals(3, read);
            Assert.assertEquals('A', buf[offset]);
            Assert.assertEquals('B', buf[offset + 1]);
            Assert.assertEquals('C', buf[offset + 2]);
        }
    }
}
